<?php include "../includes/header.php"; ?><h2>Task 3 - Function With Array</h2><div class="result"><?php function getArraySum($numbers){$sum=0; foreach($numbers as $number){$sum+=$number;} return $sum;} $numbers=[10,20,30,40,50]; echo "Array: ".implode(", ",$numbers)."<br>Sum = ".getArraySum($numbers); ?><?php if(isset($message)) echo $message; ?></div><a href="../index.php" class="btn btn-secondary mt-3">Back</a><?php include "../includes/footer.php"; ?>